    const radius = damageRadiusScale(amount) * (isAxe ? 1.0 : 0.9) * profile.length * (offhand ? 0.92 : 1.0);
    const lw = (isAxe ? 0.18 : 0.13) * damageLineWidthScale(amount) * profile.widthScale;

